-- 02_visa_types.sql
-- One verified main visitor visa per destination (12 rows).
-- Rebuilt on 2026-11-25. Rules used:
--   * Only facts found on official government / embassy pages are stored. Anything not
--     found there is NULL (never 0, never a guess). See the report for the sources.
--   * last_verified is set only when every value in the row comes from an official page.
--     Rows with last_verified NULL (FR, PL, SA, CN) still need checking.
--   * Documents and steps are English only. Other languages fall back to English in the app.
-- Requires migration 002 (allows NULL for unknown values).
-- Re-running this file OVERWRITES these rows, including any manual edits you made to them.

BEGIN;

INSERT INTO public.visa_types
  (destination_id, code, icon, name, description, stay_days_max, processing_days_min,
   processing_days_max, fee_amount, fee_currency, apply_url, embassy_url, source_url,
   last_verified, default_mandatory_docs, default_supporting_docs, default_steps)
SELECT d.id, v.code, v.icon, v.name, v.description, v.stay::int, v.pmin::int, v.pmax::int,
       v.fee::numeric, v.cur::char(3), v.apply, v.emb, v.src, v.lv::date,
       v.mand, v.supp, v.steps
FROM (VALUES
  ('US', 'B1B2', '✈️', '{"ar": "B1/B2 سياحة وأعمال", "en": "B1/B2 Tourist & Business", "es": "B1/B2 Turismo y Negocios", "fr": "B1/B2 Tourisme & Affaires"}'::jsonb, '{"ar": "الزيارات العامة والسياحة واجتماعات الأعمال.", "en": "General visits, tourism and business meetings.", "es": "Visitas generales, turismo y reuniones de negocios.", "fr": "Visites générales, tourisme et réunions d’affaires."}'::jsonb, NULL, NULL, NULL, 185, 'USD', 'https://ceac.state.gov/genniv/', 'https://www.usembassy.gov/', 'https://travel.state.gov/content/travel/en/us-visas/tourism-visit/visitor.html', '2026-11-25', '{"en": ["Valid passport", "DS-160 confirmation page (printed, with the barcode)", "Receipt for the visa application fee, if you must pay before your interview", "Photo: you upload it with the DS-160. Bring a printed photo only if the upload failed"]}'::jsonb, '{"en": ["Documents that show your purpose of travel and your ties to your home country. A consular officer may ask for them at the interview"]}'::jsonb, '{"en": ["Complete the online DS-160 nonimmigrant visa application and upload your photo.", "Print the DS-160 confirmation page to bring to your interview.", "Pay the visa application fee if you are required to pay before the interview ($185 for most visitor visas).", "Schedule your visa interview at the U.S. embassy or consulate.", "Attend the interview with your documents. If approved, you may have to pay a visa issuance fee (depends on your nationality) and arrange the return of your passport."]}'::jsonb),
  ('GB', 'STANDARD_VISITOR', '✈️', '{"ar": "زائر عادي", "en": "Standard Visitor", "es": "Visitante estándar", "fr": "Visiteur standard"}'::jsonb, '{"ar": "تأشيرة زائر عادي لمدة تصل إلى 6 أشهر.", "en": "Standard visitor visa for up to 6 months.", "es": "Visa de visitante estándar por hasta 6 meses.", "fr": "Visa de visiteur standard pour 6 mois maximum."}'::jsonb, 180, NULL, 21, 135, 'GBP', 'https://visas-immigration.service.gov.uk/apply-visa-type/visit', 'https://www.gov.uk/find-a-visa-application-centre', 'https://www.gov.uk/standard-visitor/apply-standard-visitor-visa', '2026-11-25', '{"en": ["Passport or travel document valid for the whole of your stay in the UK", "Fingerprints and a photo, taken at your visa application centre appointment", "Documents showing you are eligible for a Standard Visitor visa. The visa application centre tells you what to bring"]}'::jsonb, '{"en": ["Your travel history for the past 10 years", "Your employer''s address and telephone number", "Details of anyone paying for your trip", "Details of family members in the UK", "TB test certificate. Only needed if you are visiting for more than 6 months", "Certified English or Welsh translations of any documents in another language"]}'::jsonb, '{"en": ["Apply online and pay the £135 fee. The earliest you can apply is 3 months before you travel.", "Book and attend an appointment at a visa application centre to give your fingerprints and photo and show your documents.", "Wait for a decision. It usually takes up to 3 weeks.", "If you are successful you get an eVisa (a digital record). You view it by creating a UK Visas and Immigration account."]}'::jsonb),
  ('CA', 'TRV', '✈️', '{"ar": "تأشيرة زائر (TRV)", "en": "Visitor Visa (TRV)", "es": "Visa de visitante (TRV)", "fr": "Visa de visiteur (TRV)"}'::jsonb, '{"ar": "تأشيرة زائر مقيم مؤقت.", "en": "Temporary resident visitor visa.", "es": "Visa de residente temporal visitante.", "fr": "Visa de résident temporaire visiteur."}'::jsonb, NULL, NULL, NULL, 100, 'CAD', 'https://www.canada.ca/en/immigration-refugees-citizenship/services/visit-canada/apply-visitor-visa.html', NULL, 'https://ircc.canada.ca/visit-visiter/en/final-steps-visa-online', '2026-11-25', '{"en": ["Valid passport (colour copy of the photo page and any pages with stamps or visas)", "Digital photo that meets IRCC specifications", "Proof of funds or support for your stay", "Documents showing that you plan to enter and leave Canada (purpose of travel)"]}'::jsonb, '{"en": ["Letter of invitation from someone in Canada, if applicable", "Medical exam, if required"]}'::jsonb, '{"en": ["Collect the documents that show you meet the criteria for a visitor visa.", "Apply online: create an IRCC account, upload your documents and pay the CAD 100 visa fee. Add the CAD 85 biometrics fee if you have not given biometrics in the past 10 years.", "Give your fingerprints and photo (biometrics) after you apply.", "If your application is approved, IRCC asks you to send your passport so the visa can be issued."]}'::jsonb),
  ('DE', 'SCHENGEN_C', '✈️', '{"ar": "إقامة قصيرة شنغن (النوع ج)", "en": "Schengen Short-Stay (Type C)", "es": "Estancia corta Schengen (Tipo C)", "fr": "Séjour court Schengen (Type C)"}'::jsonb, '{"ar": "تأشيرة شنغن قصيرة المدى لمدة تصل إلى 90 يومًا.", "en": "Short-stay Schengen visa for up to 90 days.", "es": "Visa Schengen de corta estancia para 90 días máximo.", "fr": "Visa Schengen de court séjour pour 90 jours maximum."}'::jsonb, 90, NULL, 15, 90, 'EUR', 'https://www.auswaertiges-amt.de/en/visa-service/215870-215870', NULL, 'https://www.auswaertiges-amt.de/en/visa-service/215870-215870', '2026-11-25', '{"en": ["Valid passport", "Completed and signed Schengen visa application form", "Recent biometric photo(s). The number depends on the mission", "Travel health insurance valid in all Schengen states for your whole stay, with at least €30,000 coverage", "Proof of accommodation, for example hotel bookings or an invitation from your host", "Proof of sufficient financial means for your stay", "Proof of the purpose of your trip, for example an itinerary"]}'::jsonb, '{"en": ["Copies of previous Schengen visas, if any", "Proof of employment or income. The period of bank statements asked for varies by mission", "Flight reservation. Some missions ask you not to buy tickets before the visa is issued"]}'::jsonb, '{"en": ["Complete the online application form (VIDEX) and print it.", "Book an appointment at the German embassy or consulate, or at its visa application centre (VFS Global or TLScontact, depending on where you apply).", "Submit your application and documents in person. You can apply up to 6 months before you travel. Pay the €90 fee (€45 for children aged 6 to 11, free for under 6).", "Wait for the decision. It usually takes up to 15 calendar days and can take longer. Your passport stays with the mission until then."]}'::jsonb),
  ('CH', 'SCHENGEN_C', '✈️', '{"ar": "إقامة قصيرة شنغن (النوع ج)", "en": "Schengen Short-Stay (Type C)", "es": "Estancia corta Schengen (Tipo C)", "fr": "Séjour court Schengen (Type C)"}'::jsonb, '{"ar": "تأشيرة شنغن قصيرة المدى لمدة تصل إلى 90 يومًا.", "en": "Short-stay Schengen visa for up to 90 days.", "es": "Visa Schengen de corta estancia para 90 días máximo.", "fr": "Visa Schengen de court séjour pour 90 jours maximum."}'::jsonb, 90, NULL, 15, 90, 'EUR', 'https://www.swiss-visa.ch/', NULL, 'https://www.swiss-visa.ch/', '2026-11-25', '{"en": ["Valid passport", "Completed and signed Schengen visa application form", "Recent biometric photo(s). The number depends on the mission", "Travel health insurance valid in all Schengen states for your whole stay, with at least €30,000 coverage", "Proof of accommodation, for example hotel bookings or an invitation from your host", "Proof of sufficient financial means for your stay", "Proof of the purpose of your trip, for example an itinerary"]}'::jsonb, '{"en": ["Copies of previous Schengen visas, if any", "Proof of employment or income. The period of bank statements asked for varies by mission", "Flight reservation. Some missions ask you not to buy tickets before the visa is issued"]}'::jsonb, '{"en": ["Fill in the online application form at swiss-visa.ch and print it.", "Submit it with your documents at the Swiss representation or its visa application centre (often run by VFS Global).", "Pay the €90 fee (children aged 6 to 11 pay €45, under 6 are free).", "Wait for the decision. It can take up to 15 days from receipt of your application."]}'::jsonb),
  ('FR', 'SCHENGEN_C', '✈️', '{"ar": "إقامة قصيرة شنغن (النوع ج)", "en": "Schengen Short-Stay (Type C)", "es": "Estancia corta Schengen (Tipo C)", "fr": "Séjour court Schengen (Type C)"}'::jsonb, '{"ar": "تأشيرة شنغن قصيرة المدى لمدة تصل إلى 90 يومًا.", "en": "Short-stay Schengen visa for up to 90 days.", "es": "Visa Schengen de corta estancia para 90 días máximo.", "fr": "Visa Schengen de court séjour pour 90 jours maximum."}'::jsonb, 90, NULL, 15, 90, 'EUR', NULL, NULL, NULL, NULL, '{"en": ["Valid passport", "Completed and signed Schengen visa application form", "Recent biometric photo(s). The number depends on the mission", "Travel health insurance valid in all Schengen states for your whole stay, with at least €30,000 coverage", "Proof of accommodation, for example hotel bookings or an invitation from your host", "Proof of sufficient financial means for your stay", "Proof of the purpose of your trip, for example an itinerary"]}'::jsonb, '{"en": ["Copies of previous Schengen visas, if any", "Proof of employment or income. The period of bank statements asked for varies by mission", "Flight reservation. Some missions ask you not to buy tickets before the visa is issued"]}'::jsonb, '{"en": ["Find the embassy, consulate or visa application centre responsible for your place of residence.", "Complete the application form and gather your documents.", "Attend your appointment, give your fingerprints and photo, and pay the €90 fee (children aged 6 to 11 pay €45, under 6 are free).", "Wait for the decision. Schengen visas are usually decided within 15 calendar days, but it can take longer."]}'::jsonb),
  ('PL', 'SCHENGEN_C', '✈️', '{"ar": "إقامة قصيرة شنغن (النوع ج)", "en": "Schengen Short-Stay (Type C)", "es": "Estancia corta Schengen (Tipo C)", "fr": "Séjour court Schengen (Type C)"}'::jsonb, '{"ar": "تأشيرة شنغن قصيرة المدى لمدة تصل إلى 90 يومًا.", "en": "Short-stay Schengen visa for up to 90 days.", "es": "Visa Schengen de corta estancia para 90 días máximo.", "fr": "Visa Schengen de court séjour pour 90 jours maximum."}'::jsonb, 90, NULL, 15, 90, 'EUR', NULL, NULL, NULL, NULL, '{"en": ["Valid passport", "Completed and signed Schengen visa application form", "Recent biometric photo(s). The number depends on the mission", "Travel health insurance valid in all Schengen states for your whole stay, with at least €30,000 coverage", "Proof of accommodation, for example hotel bookings or an invitation from your host", "Proof of sufficient financial means for your stay", "Proof of the purpose of your trip, for example an itinerary"]}'::jsonb, '{"en": ["Copies of previous Schengen visas, if any", "Proof of employment or income. The period of bank statements asked for varies by mission", "Flight reservation. Some missions ask you not to buy tickets before the visa is issued"]}'::jsonb, '{"en": ["Find the embassy, consulate or visa application centre responsible for your place of residence.", "Complete the application form and gather your documents.", "Attend your appointment, give your fingerprints and photo, and pay the €90 fee (children aged 6 to 11 pay €45, under 6 are free).", "Wait for the decision. Schengen visas are usually decided within 15 calendar days, but it can take longer."]}'::jsonb),
  ('AE', 'TOURIST_30', '✈️', '{"ar": "تأشيرة سياحية (دخول واحد 30 يومًا)", "en": "Tourist Visa (30-day single entry)", "es": "Visa de turista (entrada única 30 días)", "fr": "Visa touristique (entrée unique 30 jours)"}'::jsonb, '{"ar": "تأشيرة سياحية لدخول واحد لمدة 30 يومًا.", "en": "30-day single-entry tourist visa.", "es": "Visa de turista de entrada única de 30 días.", "fr": "Visa touristique à entrée unique de 30 jours."}'::jsonb, 30, NULL, NULL, 200, 'AED', 'https://u.ae/en/information-and-services/visa-and-emirates-id/Types-of-visas/tourist-visa', NULL, 'https://gdrfad.gov.ae/en/node/13896', '2026-11-25', '{"en": []}'::jsonb, '{"en": []}'::jsonb, '{"en": ["Check that you are not eligible for visa-free entry or visa on arrival. The tourist visa is for travellers who are not.", "Ask a UAE-based airline, licensed travel agent or hotel to arrange the visa, or apply online through the ICP or Dubai GDRFA services. UAE embassies do not issue tourist visas.", "Pay the fee: AED 200 plus 5% VAT for a 30-day single-entry visa. Airlines and agents may add their own charges."]}'::jsonb),
  ('SA', 'TOURIST_EVISA', '✈️', '{"ar": "تأشيرة سياحية إلكترونية", "en": "Tourist eVisa", "es": "Visa de turista electrónico", "fr": "Visa touristique électronique"}'::jsonb, '{"ar": "تأشيرة سياحية إلكترونية صالحة لمدة 365 يومًا.", "en": "Tourist electronic visa valid for 365 days.", "es": "Visa de turista electrónico válido por 365 días.", "fr": "Visa touristique électronique valable 365 jours."}'::jsonb, 90, NULL, NULL, NULL, NULL, 'https://visa.visitsaudi.com/', NULL, 'https://visa.visitsaudi.com/', NULL, '{"en": []}'::jsonb, '{"en": []}'::jsonb, '{"en": ["Check that your nationality is on the list of eligible countries on the official Saudi eVisa portal.", "Apply online on the official portal and pay the fee. The portal shows the current price."]}'::jsonb),
  ('JP', 'SHORT_STAY', '✈️', '{"ar": "تأشيرة إقامة قصيرة (دخول واحد)", "en": "Short-Term Stay Visa (single entry)", "es": "Visa de estancia de corta duración (entrada única)", "fr": "Visa de séjour de courte durée (entrée unique)"}'::jsonb, '{"ar": "تأشيرة إقامة قصيرة لدخول واحد.", "en": "Single-entry short-term stay visa.", "es": "Visa de estancia de corta duración de entrada única.", "fr": "Visa de séjour de courte durée à entrée unique."}'::jsonb, NULL, NULL, NULL, 15000, 'JPY', NULL, NULL, 'https://www.mofa.go.jp/j_info/visit/visa/procedure/pagewe_000001_00391.html', '2026-11-25', '{"en": []}'::jsonb, '{"en": []}'::jsonb, '{"en": ["Check whether your nationality is visa-exempt. Japan has visa exemption arrangements with 74 countries and regions.", "If you need a visa, apply through the Japanese embassy or consulate (or its authorised agency) for your place of residence.", "Pay the fee in local currency. For a single-entry visa it is about ¥15,000 from 1 July 2026."]}'::jsonb),
  ('CN', 'L', '✈️', '{"ar": "تأشيرة سياحية L", "en": "L Tourist Visa", "es": "Visa de turista L", "fr": "Visa touristique L"}'::jsonb, '{"ar": "تأشيرة سياحية من الفئة L.", "en": "L category tourist visa.", "es": "Visa de turista categoría L.", "fr": "Visa touristique catégorie L."}'::jsonb, NULL, NULL, NULL, NULL, NULL, 'https://visaforchina.cn/', NULL, NULL, NULL, '{"en": []}'::jsonb, '{"en": []}'::jsonb, '{"en": ["Check whether you can enter without a visa. Citizens of many countries can stay up to 30 days visa-free until 31 December 2026.", "Otherwise apply for a visa at the Chinese embassy or consulate, or its visa application service centre, for your place of residence.", "Fees depend on your nationality and where you apply. Reduced fees apply until 31 December 2026, and service-centre charges are extra."]}'::jsonb),
  ('CN', 'M', '💼', '{"ar": "تأشيرة أعمال (تجارة) M", "en": "M Business (Trade) Visa", "es": "Visa de negocios (comercio) M", "fr": "Visa affaires (commerce) M"}'::jsonb, '{"ar": "تأشيرة أعمال/تجارة من الفئة M.", "en": "M category business/trade visa.", "es": "Visa de negocios/comercio categoría M.", "fr": "Visa affaires/commerce catégorie M."}'::jsonb, NULL, NULL, NULL, NULL, NULL, 'https://visaforchina.cn/', NULL, NULL, NULL, '{"en": []}'::jsonb, '{"en": []}'::jsonb, '{"en": ["Check whether you can enter without a visa. Citizens of many countries can stay up to 30 days visa-free until 31 December 2026.", "Otherwise apply for a visa at the Chinese embassy or consulate, or its visa application service centre, for your place of residence.", "Fees depend on your nationality and where you apply. Reduced fees apply until 31 December 2026, and service-centre charges are extra.", "Business (M) visas generally need an invitation from a Chinese company or trade partner. Check your embassy''s document list."]}'::jsonb)
) AS v(iso, code, icon, name, description, stay, pmin, pmax, fee, cur, apply, emb, src, lv, mand, supp, steps)
JOIN public.countries d ON d.iso_code = v.iso
ON CONFLICT (destination_id, code) DO UPDATE SET
  icon = EXCLUDED.icon, name = EXCLUDED.name, description = EXCLUDED.description,
  stay_days_max = EXCLUDED.stay_days_max, processing_days_min = EXCLUDED.processing_days_min,
  processing_days_max = EXCLUDED.processing_days_max, fee_amount = EXCLUDED.fee_amount,
  fee_currency = EXCLUDED.fee_currency, apply_url = EXCLUDED.apply_url,
  embassy_url = EXCLUDED.embassy_url, source_url = EXCLUDED.source_url,
  last_verified = EXCLUDED.last_verified,
  default_mandatory_docs = EXCLUDED.default_mandatory_docs,
  default_supporting_docs = EXCLUDED.default_supporting_docs,
  default_steps = EXCLUDED.default_steps, updated_at = now();

COMMIT;
